async function sessionStartAction(options: SessionOptions): Promise<void> {
  try {
    const ctx = await initContext();

    // Check shadow worktree health at session startup
    if (ctx.shadow?.enabled) {
      const status = await getShadowStatus(ctx.shadow.projectRoot);
      if (!status.healthy) {
        console.log(chalk.yellow('⚠ Shadow branch worktree has issues:'));
        if (!status.branchExists) {
          console.log(chalk.gray('  - Branch is missing'));
        }
        if (!status.worktreeExists) {
          console.log(chalk.gray('  - Worktree directory is missing'));
        }
        if (status.worktreeExists && !status.worktreeLinked) {
          console.log(chalk.gray('  - Worktree is not properly linked'));
        }
        console.log('');
        console.log(chalk.gray('Attempting automatic repair...'));
        const repairResult = await repairShadow(ctx.shadow.projectRoot);
        if (repairResult.success) {
          console.log(chalk.green('✓ Shadow branch worktree repaired'));
          console.log('');
        } else {
          console.log(chalk.red(`✗ Repair failed: ${repairResult.error || 'Unknown error'}`));
          console.log(chalk.gray('Run `kspec shadow status` for details'));
          console.log('');
        }
      }
    }

    // AC-2: Pull remote changes before showing session context
    let syncResult: ShadowSyncResult | null = null;
    if (ctx.shadow?.enabled) {
      syncResult = await shadowPull(ctx.shadow.worktreeDir);

