  describe('meta set', () => {
    it('should update agent name and description', () => {
      // Create an agent
      kspec('meta add agent --id update-agent --name "Original Name"', tempDir);

      // Update it
      const output = kspec(
        'meta set @update-agent --name "Updated Name" --description "New description"',
        tempDir
