`
    );

    // Add includes to meta manifest
    const metaPath = path.join(tempDir, 'kynetic.meta.yaml');
    let metaContent = await fs.readFile(metaPath, 'utf-8');
    metaContent += '\nincludes:\n  - meta/conventions.yaml\n';
