/**
 * Log command - search git history by spec/task reference
 */

import { Command } from 'commander';
import { execSync } from 'node:child_process';
import chalk from 'chalk';
import {
  initContext,
  loadAllTasks,
  loadAllItems,
  ReferenceIndex,
} from '../../parser/index.js';
import { output, error, info } from '../output.js';
import { isGitRepo } from '../../utils/git.js';
import { errors } from '../../strings/index.js';
import { EXIT_CODES } from '../exit-codes.js';

export interface LogCommit {
  hash: string;
  fullHash: string;
  date: Date;
  subject: string;
  author: string;
}

/**
 * Check if a git repo has any commits
 */
function hasCommits(cwd?: string): boolean {
  try {
    execSync('git rev-parse HEAD', {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    return true;
  } catch {
    return false;
  }
}

/**
 * Search git log for commits with trailer pattern
 */
function searchCommits(
  pattern: string,
  options: {
    limit: number;
    since?: string;
    cwd?: string;
    passthroughArgs?: string[];
  }
): LogCommit[] {
  const { limit, since, cwd, passthroughArgs = [] } = options;

  // Escape special regex characters in pattern except @
  const escapedPattern = pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  let cmd = `git log --grep="${escapedPattern}" --format="%H|%aI|%s|%an" -n ${limit}`;
  if (since) {
    cmd += ` --since="${since}"`;
  }

  // Add passthrough args if provided
  if (passthroughArgs.length > 0) {
    cmd += ` ${passthroughArgs.join(' ')}`;
  }

  try {
    const result = execSync(cmd, {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim();

    if (!result) return [];

    return result.split('\n').map((line) => {
      const [fullHash, dateStr, subject, author] = line.split('|');
      return {
        hash: fullHash.slice(0, 7),
        fullHash,
        date: new Date(dateStr),
        subject,
        author,
      };
    });
  } catch (err: any) {
    // Check for empty repo errors
    if (err.stderr) {
      const stderr = err.stderr.toString();
      // Detect "does not have any commits yet" or "bad revision" (empty repo)
      if (stderr.includes('does not have any commits yet') || stderr.includes('bad revision')) {
        // Return empty array - caller will handle empty repo message
        return [];
      }
      // Other git errors should still be shown
      error(stderr);
      process.exit(err.status || 1);
    }
    return [];
  }
}

/**
 * Search git log with passthrough args (raw output)
 */
function searchCommitsRaw(
  patterns: string[],
  options: {
    limit: number;
    since?: string;
    cwd?: string;
    passthroughArgs: string[];
  }
): string {
  const { limit, since, cwd, passthroughArgs } = options;

  // Build grep args for all patterns
  const grepArgs = patterns.map((p) => {
    const escaped = p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return `--grep="${escaped}"`;
  });

  let cmd = `git log ${grepArgs.join(' ')} -n ${limit}`;
  if (since) {
    cmd += ` --since="${since}"`;
  }

  // Add passthrough args
  cmd += ` ${passthroughArgs.join(' ')}`;

  try {
    return execSync(cmd, {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
  } catch (err: any) {
    // Check for empty repo errors
