    const jsonl = '{"ref":"@bulk-test-1","data":{"priority":"high"}}\n{"ref":"@bulk-test-2","data":{"priority":"low"}}';
    const result = kspecRun('item patch --bulk --json', tempDir, { stdin: jsonl });

    const parsed = JSON.parse(result.stdout);
