  it('should resolve refs using existing resolution logic (slugs, ULID prefixes)', () => {
    // Create two tasks with slugs
    const task1 = kspecJson<{ task: { _ulid: string } }>(
      'task add --title "Slug Test 1" --slug test-slug-1 --priority 3',
