    expect(result.exitCode).not.toBe(0);
  });

  it('should update acceptance criterion', () => {
    // First add an AC
    kspec(
      'item ac add @test-feature --id ac-to-update --given "original given" --when "original when" --then "original then"',
      tempDir
    );

    // Update it
