    const result = kspecJson<{
      success: boolean;
      summary: { total: number; succeeded: number };
    }>(`task cancel @${task.task._ulid}`, tempDir);

    expect(result.success).toBe(true);
    expect(result.summary.total).toBe(1);
    expect(result.summary.succeeded).toBe(1);
  });

