    );
    fssync.writeFileSync(
      path.join(emptyTempDir, '.kspec', 'project.tasks.yaml'),
      'tasks:\n  - _ulid: "01TEST00000000000000000"\n    slugs: [test-task]\n    title: Test\n    status: pending\n    priority: 3\n'
    );

