it('should show friendly message when repo has no commits and ref is provided', () => {
  // Use existing tempDir with fixtures but with no commits yet
  // The setupTempFixtures creates .kspec structure but beforeEach doesn't create any commits
  // So we need to test before any commits are made
  // Actually, let's just test with the existing task-ref from fixtures
  // The key is: empty repo (no commits) + valid ref lookup = friendly message

  // Since tempDir already has git history from other tests, create isolated empty repo
  const emptyTempDir = fssync.mkdtempSync(path.join(os.tmpdir(), 'kspec-test-empty-'));
  try {
    execSync('git init', { cwd: emptyTempDir, stdio: 'ignore' });

    // Create minimal kspec structure with a valid task
    fssync.mkdirSync(path.join(emptyTempDir, '.kspec'), { recursive: true });
    fssync.writeFileSync(
      path.join(emptyTempDir, '.kspec', 'kynetic.yaml'),
      'version: "1.0"\nproject:\n  name: test\n  slug: test\n  modules: []\n'
    );
    fssync.writeFileSync(
      path.join(emptyTempDir, '.kspec', 'project.tasks.yaml'),
      'tasks:\n  - _ulid: 01TEST00000000000000000\n    slugs:\n      - test-task\n    title: Test\n    status: pending\n    priority: 3\n    created_at: "2026-01-01T00:00:00Z"\n'
    );

    const output = kspec('log @test-task', emptyTempDir);
    expect(output).toContain('No commits in repository yet');
    expect(output).not.toContain('fatal');
  } finally {
    fssync.rmSync(emptyTempDir, { recursive: true, force: true });
  }
});

