    // Create three tasks and start them
    const task1 = kspecJson<{ task: { _ulid: string } }>(
      'task add --title "Task 1" --priority 3',
      tempDir
    );
    const task2 = kspecJson<{ task: { _ulid: string } }>(
      'task add --title "Task 2" --priority 3',
      tempDir
