import {
  kspec as kspecRun,
  kspecOutput as kspec,
  kspecJson,
  setupTempFixtures,
  cleanupTempDir,
  FIXTURES_DIR,
  git,
  initGitRepo,
} from './helpers/cli';

describe('Integration: validate', () => {
