      cwd: tempDir,
      stdio: 'ignore',
    });

    // Use passthrough arg to show stat
    const output = kspec('log @test-task-pending -- --stat', tempDir);

    // Should contain stat output (file changes)
    expect(output).toContain('changed');
  });

