    expect(results[0]).toHaveProperty('slug');
    expect(results[0]).toHaveProperty('spec_ref');
    expect(results[0]).toHaveProperty('depends_on');
    expect(results[0]).toHaveProperty('action');

    // First item (parent) should have no deps
