import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { setupTempFixtures, cleanupTempDir, kspecOutput as kspec, kspecJson } from './helpers/cli';

describe('Integration: task add --description', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @spec-task-add-description ac-1
  it('should create task with description when provided', () => {
    const output = kspec(
      'task add --title "Test Task" --description "Detailed description here" --slug desc-test-1',
      tempDir
    );
    expect(output).toContain('Created task');

    const task = kspecJson<{ description?: string }>(
      'task get @desc-test-1',
      tempDir
    );

    expect(task.description).toBe('Detailed description here');
  });

  // AC: @spec-task-add-description ac-2
  it('should create task without description when not provided', () => {
    const output = kspec(
      'task add --title "Test Task No Desc" --slug no-desc-test',
      tempDir
    );
    expect(output).toContain('Created task');

    const task = kspecJson<{ description?: string }>(
      'task get @no-desc-test',
      tempDir
    );

    // Description should be absent (not empty string)
    expect(task.description).toBeUndefined();
  });

  // AC: @spec-task-add-description ac-3
  it('should preserve multiline descriptions', () => {
    // Use $'...' syntax to interpret \n as newlines in bash
    const multilineDesc = 'Line 1\nLine 2\nLine 3';
    const output = kspec(
      `task add --title "Multiline Task" --description $'${multilineDesc}' --slug multiline-test`,
      tempDir
    );
    expect(output).toContain('Created task');

    const task = kspecJson<{ description?: string }>(
      'task get @multiline-test',
      tempDir
    );

    // The \n should be interpreted as actual newlines
    expect(task.description).toBe('Line 1\nLine 2\nLine 3');
  });

  // AC: @spec-task-add-description ac-4
  it('should handle special characters in description', () => {
    // Test various special characters that might cause YAML issues
    // Use single quotes to preserve double quotes, escape single quotes
    const specialDesc = 'Contains: colons, "quotes", and \'singles\'';
    const output = kspec(
      `task add --title "Special Chars Task" --description 'Contains: colons, "quotes", and '"'"'singles'"'"'' --slug special-test`,
      tempDir
    );
    expect(output).toContain('Created task');

    const task = kspecJson<{ description?: string }>(
      'task get @special-test',
      tempDir
    );

    expect(task.description).toBe(specialDesc);
  });

  // AC: @spec-task-add-description ac-5
  it('should include description in JSON output', () => {
    const desc = 'Test description for JSON';
    const output = kspecJson<{ task: { description?: string } }>(
      `task add --title "JSON Test" --description "${desc}" --slug json-desc-test --json`,
      tempDir
    );

    expect(output.task.description).toBe(desc);
  });

  // AC: @spec-task-add-description ac-6
  it('should treat empty description as omitted', () => {
    const output = kspec(
      'task add --title "Empty Desc Task" --description "" --slug empty-desc-test',
      tempDir
    );
    expect(output).toContain('Created task');

    const task = kspecJson<{ description?: string }>(
      'task get @empty-desc-test',
      tempDir
    );

    // Empty string should be treated as no description (field omitted)
    expect(task.description).toBeUndefined();
  });

  // AC: @spec-task-add-description ac-6 - whitespace-only also omitted
  it('should treat whitespace-only description as omitted', () => {
    const output = kspec(
      'task add --title "Whitespace Desc Task" --description "   " --slug whitespace-desc-test',
      tempDir
    );
    expect(output).toContain('Created task');

    const task = kspecJson<{ description?: string }>(
      'task get @whitespace-desc-test',
      tempDir
    );

    // Whitespace-only should be treated as no description
    expect(task.description).toBeUndefined();
  });

  // Inherited AC: @trait-json-output ac-1 - JSON output validation
  it('should output valid JSON with --json flag', () => {
    const output = kspecJson<{ task: { title: string; description?: string } }>(
      'task add --title "JSON Validation" --description "Test desc" --json',
      tempDir
    );

    // Should have valid structure
    expect(output.task).toBeDefined();
    expect(output.task.title).toBe('JSON Validation');
    expect(output.task.description).toBe('Test desc');
  });
});

    }
  });

// kspec task add
task
  .command('add')
  .description('Create a new task')
  .requiredOption('--title <title>', 'Task title')
  .option('--description <description>', 'Task description')
  .option('--type <type>', 'Task type (task, epic, bug, spike, infra)', 'task')
  .option('--spec-ref <ref>', 'Reference to spec item')
  .option('--meta-ref <ref>', 'Reference to meta item (workflow, agent, or convention)')
  .option('--priority <n>', 'Priority (1-5)', '3')
  .option('--slug <slug>', 'Human-friendly slug')
  .option('--tag <tag...>', 'Tags')
  .option('--automation <status>', 'Automation eligibility (eligible, needs_review, manual_only)')
  .action(async (options) => {
    try {
      const ctx = await initContext();
      const tasks = await loadAllTasks(ctx);
      const items = await loadAllItems(ctx);

      // Load meta items for validation
      const { loadMetaContext } = await import('../../parser/meta.js');
      const metaContext = await loadMetaContext(ctx);
      const allMetaItems = [
        ...metaContext.agents,
        ...metaContext.workflows,
        ...metaContext.conventions,
        ...metaContext.observations,
      ];

      // Build index for reference validation
      const refIndex = new ReferenceIndex(tasks, items, allMetaItems);

      // Check slug uniqueness if provided
      if (options.slug) {
        const slugCheck = checkSlugUniqueness(refIndex, [options.slug]);
        if (!slugCheck.ok) {
          error(errors.slug.alreadyExists(slugCheck.slug, slugCheck.existingUlid));
          process.exit(EXIT_CODES.CONFLICT);
        }
      }

      // Validate meta_ref if provided (AC-meta-ref-3, AC-meta-ref-4)
      if (options.metaRef) {
        const metaRefResult = refIndex.resolve(options.metaRef);

        if (!metaRefResult.ok) {
          error(errors.reference.metaRefNotFound(options.metaRef));
          process.exit(EXIT_CODES.NOT_FOUND);
        }

        // Check if the resolved item is a meta item (not a spec item or task)
        const isTask = tasks.some(t => t._ulid === metaRefResult.ulid);
        const isSpecItem = items.some(i => i._ulid === metaRefResult.ulid);

        if (isTask || isSpecItem) {
          error(errors.reference.metaRefPointsToSpec(options.metaRef));
          process.exit(EXIT_CODES.NOT_FOUND);
        }
      }

      // AC: @task-automation-eligibility ac-13 - validate automation if provided
      let automationValue: 'eligible' | 'needs_review' | 'manual_only' | undefined;
      if (options.automation) {
        const validStatuses = ['eligible', 'needs_review', 'manual_only'];
        if (!validStatuses.includes(options.automation)) {
          error(`Invalid automation status: ${options.automation}. Must be one of: ${validStatuses.join(', ')}`);
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }
        automationValue = options.automation as 'eligible' | 'needs_review' | 'manual_only';
      }

      // AC: @spec-task-add-description ac-6 - Omit description if empty string
      const descriptionValue = options.description && options.description.trim() !== ''
        ? options.description
        : undefined;

      const input: TaskInput = {
        title: options.title,
        description: descriptionValue,
        type: options.type,
        spec_ref: options.specRef || null,
        meta_ref: options.metaRef || null,
        priority: parseInt(options.priority, 10),
        slugs: options.slug ? [options.slug] : [],
        tags: options.tag || [],
        automation: automationValue,
      };

      const newTask = createTask(input);
      await saveTask(ctx, newTask);
      await commitIfShadow(ctx.shadow, 'task-add', newTask.slugs[0] || newTask._ulid.slice(0, 8), newTask.title);

      // Build index including the new task for accurate short ULID
      const index = new ReferenceIndex([...tasks, newTask], items, allMetaItems);
      success(`Created task: ${index.shortUlid(newTask._ulid)}`, { task: newTask });
    } catch (err) {
      error(errors.failures.createTask, err);

