describe('Integration: task completion enforcement', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    initGitRepo(tempDir); // Shadow commands require git repo
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

