      'task get @test-task-pending',
      tempDir
    );
    const task2 = kspecJson<{ status: string }>(
      'task get @test-task-blocked',
      tempDir
    );
    expect(task1.status).toBe('pending_review');
    expect(task2.status).toBe('in_progress');

