      summary: { total: number; succeeded: number };
    }>(`task cancel --refs @${task1.task._ulid} @${task2.task._ulid}`, tempDir);

    expect(result.success).toBe(true);
    expect(result.summary.total).toBe(2);
    expect(result.summary.succeeded).toBe(2);
  });

