  it('should batch delete multiple tasks', () => {
    // Create three tasks
    const task1 = kspecJson<{ task: { _ulid: string } }>(
      'task add --title "Delete 1" --priority 3',
      tempDir
    );
    const task2 = kspecJson<{ task: { _ulid: string } }>(
