    kspec('meta focus @task-test', tempDir);
    kspec('meta thread add "Thread 1"', tempDir);

    interface ContextJson {
      focus: string | null;
      threads: string[];
      open_questions: string[];
      updated_at: string;
    }

    const data = kspecJson<ContextJson>('meta context --clear', tempDir);

