    11→/**
    12→ * Result of a single ref operation within a batch
    13→ */
    14→export interface BatchOperationResult {
    15→  ref: string;
    16→  ulid: string | null;
    17→  status: 'success' | 'error';
    18→  error?: string;
    19→  message?: string;
    20→  data?: unknown;
    21→}
    22→
    23→/**
    24→ * Summary of batch operation results
    25→ */
    26→export interface BatchSummary {
    27→  total: number;
    28→  succeeded: number;
    29→  failed: number;
    30→}
    31→
    32→/**
    33→ * Complete result of a batch operation
    34→ */
    35→export interface BatchResult {
    36→  success: boolean;
    37→  summary: BatchSummary;
    38→  results: BatchOperationResult[];
    39→}
    40→
    41→/**
    42→ * Options for executeBatchOperation
    43→ */
    44→export interface BatchOperationOptions<TItem, TContext> {
    45→  /** The positional ref argument (if provided) */
    46→  positionalRef?: string;
    47→  /** The --refs flag values (if provided) */
    48→  refsFlag?: string[];
    49→  /** Context needed for operations */
    50→  context: TContext;
    51→  /** All items to search through */
    52→  items: TItem[];
    53→  /** Reference index for resolution */
    54→  index: ReferenceIndex;
    55→  /** Function to resolve a ref to an item - returns { item, error? } */
    56→  resolveRef: (ref: string, items: TItem[], index: ReferenceIndex) => { item: TItem | null; error?: string };
    57→  /** Function to execute the operation on a single item */
    58→  executeOperation: (item: TItem, context: TContext) => Promise<{ success: boolean; message?: string; error?: string; data?: unknown }>;
    59→  /** Function to extract ULID from an item */
    60→  getUlid: (item: TItem) => string;
    61→}
    62→
    63→/**
    64→ * Execute a batch operation with support for single-ref (positional) or multi-ref (--refs flag).
    65→ * Handles mutual exclusion, partial failures, and unified output formatting.
    66→ *
    67→ * Returns a BatchResult object. Caller should use formatBatchOutput() to render results.
    68→ */
    69→export async function executeBatchOperation<TItem, TContext>(
    70→  options: BatchOperationOptions<TItem, TContext>
    71→): Promise<BatchResult> {
    72→  const { positionalRef, refsFlag, context, items, index, resolveRef, executeOperation, getUlid } = options;
    73→
    74→  // AC: @multi-ref-batch ac-3 - Mutual exclusion check
    75→  if (positionalRef && refsFlag && refsFlag.length > 0) {
    76→    error('Cannot use both positional ref and --refs flag');
    77→    process.exit(EXIT_CODES.USAGE_ERROR);
    78→  }
    79→
    80→  // Determine which refs to process
    81→  let refs: string[];
    82→  if (refsFlag && refsFlag.length > 0) {
    83→    refs = refsFlag;
    84→  } else if (positionalRef) {
    85→    refs = [positionalRef];
    86→  } else {
    87→    // AC: @multi-ref-batch ac-7 - Empty refs error
    88→    error('--refs requires at least one reference');
    89→    process.exit(EXIT_CODES.USAGE_ERROR);
    90→  }
    91→
    92→  // Process each ref
    93→  const results: BatchOperationResult[] = [];
    94→
    95→  // AC: @multi-ref-batch ac-4 - Continue processing after errors (partial failure handling)
    96→  for (const ref of refs) {
    97→    try {
    98→      // AC: @multi-ref-batch ac-8 - Ref resolution uses existing logic
    99→      const resolved = resolveRef(ref, items, index);
   100→
   101→      if (!resolved.item) {
   102→        // Resolution failed - record error and continue to next ref
   103→        results.push({
   104→          ref,
   105→          ulid: null,
   106→          status: 'error',
   107→          error: resolved.error || `Failed to resolve reference: ${ref}`,
   108→        });
   109→        continue;
   110→      }
   111→
   112→      const ulid = getUlid(resolved.item);
   113→
   114→      // Execute the operation
   115→      const opResult = await executeOperation(resolved.item, context);
   116→
   117→      results.push({
   118→        ref,
   119→        ulid: index.shortUlid(ulid),
   120→        status: opResult.success ? 'success' : 'error',
   121→        message: opResult.message,
   122→        error: opResult.error,
   123→        data: opResult.data,
   124→      });
   125→    } catch (err) {
   126→      // Unexpected error during operation
   127→      results.push({
   128→        ref,
   129→        ulid: null,
   130→        status: 'error',
   131→        error: err instanceof Error ? err.message : String(err),
   132→      });
   133→    }
   134→  }
   135→
   136→  // Calculate summary
   137→  const succeeded = results.filter(r => r.status === 'success').length;
   138→  const failed = results.filter(r => r.status === 'error').length;
   139→  const summary: BatchSummary = {
   140→    total: results.length,
   141→    succeeded,
   142→    failed,
   143→  };
   144→
   145→  // Determine overall success
   146→  const success = failed === 0;
   147→
   148→  return {
   149→    success,
   150→    summary,
   151→    results,
   152→  };
   153→}
   154→
   155→/**
   156→ * Format and output batch operation results.
   157→ * Handles both human-readable and JSON output formats.
   158→ * Sets appropriate exit code based on results.
   159→ *
   160→ * AC: @multi-ref-batch ac-5 - Human output format
   161→ * AC: @multi-ref-batch ac-6 - JSON output format
   162→ */
   163→export function formatBatchOutput(result: BatchResult, operationName: string): void {
   164→  if (isJsonMode()) {
   165→    // AC: @multi-ref-batch ac-6 - JSON output
   166→    console.log(JSON.stringify(result, null, 2));
   167→  } else {
