   169→    const { summary, results } = result;
   170→
   171→    // Summary line
   172→    if (summary.total === 1) {
   173→      // Single item - no summary needed, just show result
   174→      const r = results[0];
   175→      if (r.status === 'success') {
   176→        console.log(chalk.green(`✓ ${operationName}: ${r.ulid || r.ref}`));
   177→        if (r.message) {
   178→          console.log(`  ${r.message}`);
   179→        }
   180→      } else {
   181→        console.log(chalk.red(`✗ ${operationName} failed: ${r.ref}`));
   182→        if (r.error) {
   183→          console.log(chalk.red(`  ${r.error}`));
   184→        }
   185→      }
   186→    } else {
   187→      // Multiple items - show summary
   188→      const verb = operationName.toLowerCase();
   189→      console.log(`${chalk.bold(`${operationName}d ${summary.succeeded} of ${summary.total}:`
   190→)}\n`);
   191→
   192→      // List each result
   193→      for (const r of results) {
   194→        if (r.status === 'success') {
   195→          console.log(chalk.green(`✓ ${r.ulid || r.ref}`));
   196→          if (r.message) {
   197→            console.log(`  ${r.message}`);
   198→          }
   199→        } else {
