   201→          if (r.error) {
   202→            console.log(chalk.red(`  ${r.error}`));
   203→          }
   204→        }
   205→      }
   206→    }
   207→  }
   208→
   209→  // Set exit code
   210→  // AC: @multi-ref-batch ac-4 - Partial failure exit code
   211→  if (!result.success) {
   212→    if (result.summary.succeeded > 0) {
