    try {
      kspec('task set --refs @will-succeed @will-fail --priority 1', tempDir);
      expect.fail('Should have exited with error');
    } catch (err: any) {
      // Should show partial failure in error output
      expect(err.message).toContain('Setd 1 of 2');
    }
  });

