  it('should operate on all provided references in batch mode', () => {
    kspec('task add --title "Batch 1" --slug b1', tempDir);
    kspec('task add --title "Batch 2" --slug b2', tempDir);
    kspec('task add --title "Batch 3" --slug b3', tempDir);

