/**
 * Read stdin fully with timeout (for bulk input).
 * Returns null if stdin is a TTY or empty.
 */
async function readStdinFully(): Promise<string | null> {
  if (process.stdin.isTTY) {
    return null;
  }

  return new Promise((resolve) => {
    let data = '';
    const timeout = setTimeout(() => {
      process.stdin.removeAllListeners();
      resolve(data || null);
    }, 5000); // 5 second timeout for bulk input

    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      clearTimeout(timeout);
      resolve(data || null);
    });
    process.stdin.on('error', () => {
      clearTimeout(timeout);
      resolve(null);
    });
    process.stdin.resume();
  });
}

/**
 * Read stdin if available (non-blocking for single item mode).
 * Returns null quickly if no data available.
 */
async function readStdinIfAvailable(): Promise<string | null> {
  if (process.stdin.isTTY) {
    return null;
  }

  return new Promise((resolve) => {
    let data = '';
    const timeout = setTimeout(() => {
      process.stdin.removeAllListeners();
      resolve(data || null);
    }, 100); // 100ms timeout for quick check

    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      clearTimeout(timeout);
      resolve(data || null);
    });
    process.stdin.on('error', () => {
      clearTimeout(timeout);
      resolve(null);
    });
    process.stdin.resume();
  });
}

/**
 * Parse bulk input (JSONL or JSON array)
 */
function parseBulkInput(input: string): PatchOperation[] {
  const trimmed = input.trim();

  // Try JSON array first
  if (trimmed.startsWith('[')) {
    const parsed = JSON.parse(trimmed);
    if (!Array.isArray(parsed)) {
      throw new Error(errors.validation.expectedJsonArray);
    }
    return parsed.map((item, i) => validatePatchOperation(item, i));
  }

  // Parse as JSONL (one JSON object per line)
  const lines = trimmed.split('\n').filter(line => line.trim());
  return lines.map((line, i) => {
    try {
      return validatePatchOperation(JSON.parse(line), i);
    } catch (err) {
      throw new Error(errors.validation.jsonLineError(i + 1, err instanceof Error ? err.message : 'Invalid JSON'));
    }
  });
}

/**
 * Validate a patch operation object
 */
function validatePatchOperation(obj: unknown, index: number): PatchOperation {
  if (!obj || typeof obj !== 'object') {
    throw new Error(errors.validation.patchMustBeObject(index));
  }
  const op = obj as Record<string, unknown>;
  if (typeof op.ref !== 'string' || !op.ref) {
    throw new Error(errors.validation.patchMustHaveRef(index));
  }
  if (!op.data || typeof op.data !== 'object') {
    throw new Error(errors.validation.patchMustHaveData(index));
  }
  return { ref: op.ref, data: op.data as Record<string, unknown> };
}

/**
 * Format bulk patch result for human output
 */
function formatBulkPatchResult(result: BulkPatchResult, isDryRun = false): void {
  const prefix = isDryRun ? 'Would patch' : 'Patched';

  for (const r of result.results) {
    if (r.status === 'updated') {
      console.log(chalk.green('OK'), `${prefix}: ${r.ref} (${r.ulid?.slice(0, 8)})`);
    } else if (r.status === 'error') {
      console.log(chalk.red('ERR'), `${r.ref}: ${r.error}`);
    } else {
      console.log(chalk.gray('SKIP'), r.ref);
    }
  }

  console.log('');
  console.log(chalk.bold('Summary:'));
  console.log(`  Total: ${result.summary.total}`);
  console.log(chalk.green(`  Updated: ${result.summary.updated}`));
  if (result.summary.failed > 0) {
    console.log(chalk.red(`  Failed: ${result.summary.failed}`));
  }
  if (result.summary.skipped > 0) {
    console.log(chalk.gray(`  Skipped: ${result.summary.skipped}`));
  }
}

/**
 * Tests for AC delete confirmation prompt
 *
 * Validates the confirmation prompt behavior when removing acceptance criteria.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  kspec,
  setupTempFixtures,
  cleanupTempDir,
} from './helpers/cli';

describe('AC Delete Confirmation', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    // Add a test spec item with an AC
    kspec('item add --under @bootstrap --title "Test Feature" --type feature --slug test-feature', tempDir);
    kspec('item ac add @test-feature --id ac-1 --given "user exists" --when "action performed" --then "expected result"', tempDir);
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @spec-ac-delete-confirmation ac-1
  it('should prompt for confirmation when removing AC without --force', () => {
    // When user confirms
    const result = kspec('item ac remove @test-feature ac-1', tempDir, {
      stdin: 'y',
      env: { KSPEC_TEST_TTY: '1' } // Simulate TTY for testing
    });

    expect(result.stdout).toContain('Remove acceptance criterion ac-1? [y/N]');
    expect(result.stdout).toContain('Removed acceptance criterion');
    expect(result.exitCode).toBe(0);

    // Verify AC was removed
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('0 acceptance criteria');
  });

  // AC: @spec-ac-delete-confirmation ac-2
  it('should remove AC when user confirms with y', () => {
    const result = kspec('item ac remove @test-feature ac-1', tempDir, {
      stdin: 'y',
      env: { KSPEC_TEST_TTY: '1' }
    });

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain('Removed acceptance criterion');

    // Verify removal
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('0 acceptance criteria');
  });

  // AC: @spec-ac-delete-confirmation ac-3
  it('should cancel operation when user declines with n', () => {
    const result = kspec('item ac remove @test-feature ac-1', tempDir, {
      stdin: 'n',
      expectFail: true,
      env: { KSPEC_TEST_TTY: '1' }
    });

    expect(result.exitCode).toBe(2); // USER_CANCELLED
    expect(result.stdout).toContain('Operation cancelled');

    // Verify AC still exists
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('[ac-1]');
  });

  // AC: @spec-ac-delete-confirmation ac-3
  it('should cancel operation when user enters empty response', () => {
    const result = kspec('item ac remove @test-feature ac-1', tempDir, {
      stdin: '',
      expectFail: true,
      env: { KSPEC_TEST_TTY: '1' }
    });

    expect(result.exitCode).toBe(2); // USER_CANCELLED
    expect(result.stdout).toContain('Operation cancelled');

    // Verify AC still exists
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('[ac-1]');
  });

  // AC: @spec-ac-delete-confirmation ac-4
  it('should remove AC immediately with --force flag', () => {
    const result = kspec('item ac remove @test-feature ac-1 --force', tempDir);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain('Removed acceptance criterion');
    expect(result.stdout).not.toContain('Remove acceptance criterion ac-1? [y/N]');

    // Verify removal
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('0 acceptance criteria');
  });

  // AC: @spec-ac-delete-confirmation ac-5
  it('should error in JSON mode without --force', () => {
    const result = kspec('item ac remove @test-feature ac-1 --json', tempDir, {
      expectFail: true
    });

    expect(result.exitCode).toBe(1); // VALIDATION_ERROR
    expect(result.stdout).toContain('Confirmation required. Use --force with --json');

    // Verify AC still exists
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('[ac-1]');
  });

  // AC: @spec-ac-delete-confirmation ac-6
  it('should error in non-interactive environment without --force', () => {
    // Don't provide KSPEC_TEST_TTY, stdin won't be a TTY
    const result = kspec('item ac remove @test-feature ac-1', tempDir, {
      expectFail: true
    });

    expect(result.exitCode).toBe(1); // VALIDATION_ERROR
    expect(result.stdout).toContain('Non-interactive environment. Use --force to proceed');

    // Verify AC still exists
    const listResult = kspec('item ac list @test-feature', tempDir);
    expect(listResult.stdout).toContain('[ac-1]');
  });

  // AC: @spec-ac-delete-confirmation ac-4
  it('should work in non-interactive environment with --force', () => {
    const result = kspec('item ac remove @test-feature ac-1 --force', tempDir);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain('Removed acceptance criterion');

