/**
 * Find all child items of a given item.
 * Children are items whose _path starts with the parent's path.
 * For example, if parent has path "features[0]", children would have paths like:
 * - "features[0].requirements[0]"
 * - "features[0].requirements[0].constraints[0]"
 */
export function findChildItems(parent: LoadedSpecItem, allItems: LoadedSpecItem[]): LoadedSpecItem[] {
  // If parent has no path, it's at root level - check if other items are in the same file
  if (!parent._path) {
    // Root items can have children in nested fields
    // Children would have paths that don't start with another item's path
    return allItems.filter(item => {
      if (!item._path || item._sourceFile !== parent._sourceFile) return false;
      // Check if this item's path indicates it's directly under a root-level nested field
      // E.g., "features[0]" or "requirements[1]"
      const pathParts = item._path.split('.');
      return pathParts.length === 1 && item._ulid !== parent._ulid;
    });
  }

  // For items with paths, find all items whose path starts with parent's path
  const parentPath = parent._path;
  return allItems.filter(item => {
    if (!item._path || item._ulid === parent._ulid) return false;
    // Check if item's path starts with parent's path followed by a dot
    // E.g., parent="features[0]", child="features[0].requirements[0]"
    return item._path.startsWith(parentPath + '.');
  });
}

/**
 * Check if an item is a trait with implementors.
 * Returns array of items that use this trait via the 'uses' field.
 */
export function findTraitImplementors(trait: LoadedSpecItem, allItems: LoadedSpecItem[]): LoadedSpecItem[] {
  // Check if the item is actually a trait
  if (trait.type !== 'trait') {
