            items: specItems,
            total: result.total,
            showing: specItems.length,
            grepPattern: options.grep,
            tree: options.tree,
          },
          () => {
            if (options.tree) {
              formatItemTree(specItems, options.verbose, options.grep);
            } else {
              formatItemList(specItems, options.verbose, options.grep);
            }
          }
        );
