    15→// Fixtures directory for test data
    16→export const FIXTURES_DIR = path.join(__dirname, '..', 'fixtures');
    17→
    18→/**
    19→ * Options for running kspec CLI commands
    20→ */
    21→export interface KspecOptions {
    22→  /** Input to pipe to stdin */
    23→  stdin?: string;
    24→  /** Don't throw on non-zero exit code */
    25→  expectFail?: boolean;
    26→  /** Additional environment variables */
    27→  env?: Record<string, string>;
    28→}
    29→
    30→/**
    31→ * Result from running a kspec CLI command
    32→ */
    33→export interface KspecResult {
    34→  /** Exit code (0 = success) */
    35→  exitCode: number;
    36→  /** Standard output (trimmed) */
    37→  stdout: string;
    38→  /** Standard error (trimmed) */
    39→  stderr: string;
    40→}
    41→
    42→/**
    43→ * Run a kspec CLI command
    44→ *
    45→ * @param args - CLI arguments (e.g., "task list --json")
    46→ * @param cwd - Working directory to run the command in
    47→ * @param options - Optional settings for stdin, error handling, env vars
    48→ * @returns KspecResult with exitCode, stdout, stderr
    49→ * @throws Error if command fails and expectFail is not set
    50→ *
    51→ * @example
    52→ * // Simple command
    53→ * const result = kspec('task list', tempDir);
    54→ *
    55→ * @example
    56→ * // With stdin
    57→ * const result = kspec('item set @ref --status implemented', tempDir, { stdin: 'y' });
    58→ *
    59→ * @example
    60→ * // Expecting failure
    61→ * const result = kspec('task set @ref --priority 99', tempDir, { expectFail: true });
    62→ * expect(result.exitCode).toBe(1);
    63→ */
    64→export function kspec(args: string, cwd: string, options: KspecOptions = {}): KspecResult {
    65→  const { stdin, expectFail = false, env = {} } = options;
    66→
    67→  // Build command - use shell for stdin piping
    68→  let cmd: string;
    69→  if (stdin !== undefined) {
    70→    // Escape single quotes in stdin and use printf for reliable piping
    71→    // Add newline at end for interactive prompts
    72→    const stdinWithNewline = stdin.endsWith('\n') ? stdin : stdin + '\n';
    73→    const escapedStdin = stdinWithNewline.replace(/'/g, "'\\''");
    74→    cmd = `printf '%s' '${escapedStdin}' | node ${CLI_PATH} ${args}`;
    75→  } else {
    76→    cmd = `node ${CLI_PATH} ${args}`;
    77→  }
    78→
    79→  try {
    80→    const stdout = execSync(cmd, {
    81→      cwd,
    82→      encoding: 'utf-8',
    83→      env: { ...process.env, KSPEC_AUTHOR: '@test', ...env },
    84→      shell: stdin !== undefined ? '/bin/sh' : undefined,
    85→    });
    86→    return { exitCode: 0, stdout: stdout.trim(), stderr: '' };
    87→  } catch (error: unknown) {
    88→    const execError = error as {
    89→      status?: number;
    90→      stdout?: string;
    91→      stderr?: string;
    92→      message?: string;
    93→    };
    94→
    95→    const result: KspecResult = {
    96→      exitCode: execError.status ?? 1,
    97→      stdout: (execError.stdout || '').trim(),
    98→      stderr: (execError.stderr || '').trim(),
    99→    };
   100→
   101→    if (expectFail) {
   102→      return result;
   103→    }
   104→
   105→    // For backwards compatibility: return stdout if present even on error
   106→    // (some commands exit non-zero with valid output)
   107→    if (result.stdout) {
   108→      return result;
   109→    }
   110→
   111→    throw new Error(`Command failed: ${cmd}\n${result.stderr || execError.message}`);
   112→  }
   113→}
   114→
   115→/**
   116→ * Run kspec and return just stdout (convenience wrapper)
   117→ *
   118→ * @param args - CLI arguments
   119→ * @param cwd - Working directory
   120→ * @param options - Optional settings
   121→ * @returns stdout trimmed
   122→ */
   123→export function kspecOutput(args: string, cwd: string, options: KspecOptions = {}): string {
   124→  return kspec(args, cwd, options).stdout;
   125→}
   126→
   127→/**
   128→ * Run kspec and return parsed JSON output
   129→ *
   130→ * @param args - CLI arguments (--json flag is added automatically)
   131→ * @param cwd - Working directory
   132→ * @param options - Optional settings
   133→ * @returns Parsed JSON response
   134→ */
   135→export function kspecJson<T>(args: string, cwd: string, options: KspecOptions = {}): T {
   136→  const result = kspec(`${args} --json`, cwd, options);
   137→  return JSON.parse(result.stdout);
   138→}
   139→
   140→// Legacy aliases for backwards compatibility
   141→export const kspecExpectFail = (args: string, cwd: string): string => {
   142→  const result = kspec(args, cwd, { expectFail: true });
   143→  return result.stderr || result.stdout;
   144→};
   145→
   146→export const kspecWithStatus = (args: string, cwd: string): KspecResult => {
   147→  return kspec(args, cwd, { expectFail: true });
   148→};
   149→
   150→/**
   151→ * Copy fixtures to a temp directory for isolated testing
   152→ *
   153→ * @returns Path to the temp directory
   154→ */
   155→export async function setupTempFixtures(): Promise<string> {
   156→  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'kspec-test-'));
   157→  await fs.cp(FIXTURES_DIR, tempDir, { recursive: true });
   158→  return tempDir;
   159→}
   160→
   161→/**
   162→ * Clean up a temp directory
   163→ *
   164→ * @param dir - Directory to remove
   165→ */
   166→export async function cleanupTempDir(dir: string): Promise<void> {
   167→  await fs.rm(dir, { recursive: true, force: true });
   168→}
   169→
   170→/**
   171→ * Create an empty temp directory (no fixtures)
   172→ *
   173→ * @param prefix - Optional prefix for the temp directory name
   174→ * @returns Path to the temp directory
   175→ */
   176→export async function createTempDir(prefix = 'kspec-test-'): Promise<string> {
   177→  return fs.mkdtemp(path.join(os.tmpdir(), prefix));
   178→}
   179→
   180→/**
   181→ * Initialize a git repo in a directory (useful for tests that need git)
   182→ *
   183→ * @param dir - Directory to initialize
   184→ */
   185→export function initGitRepo(dir: string): void {
   186→  execSync('git init -b main', { cwd: dir, stdio: 'pipe' });
   187→  execSync('git config user.email "test@example.com"', { cwd: dir, stdio: 'pipe' });
   188→  execSync('git config user.name "Test User"', { cwd: dir, stdio: 'pipe' });
   189→}
   190→
   191→/**
   192→ * Run a git command in a directory
   193→ *
   194→ * @param cmd - Git command (without 'git' prefix)
   195→ * @param cwd - Working directory
   196→ */
   197→export function git(cmd: string, cwd: string): void {
   198→  execSync(`git ${cmd}`, { cwd, stdio: 'pipe' });
