  it('should cancel operation when user enters empty response', () => {
    const result = kspec('item ac remove @ac-test-feature ac-1', tempDir, {
      stdin: '',
      expectFail: true,
      env: { KSPEC_TEST_TTY: '1' }
    });

    expect(result.exitCode).toBe(2); // USAGE_ERROR (user cancelled)
