    }>(`task delete --refs @${task1.task._ulid} @${task2.task._ulid} @${task3.task._ulid} --force`, tempDir);

    expect(result.success).toBe(true);
    expect(result.summary.total).toBe(3);
    expect(result.summary.succeeded).toBe(3);
